    onChange({ navigation, points: route?.ok ? route.points : start ? [start] : [], pick(point) {
      if (!navigation) return;
      const valid = navigation.route(point, point);
      if (!valid.ok) {
        setPickError("Choose a point on the walkable floor, away from walls and edges.");
        // A failed replacement must not leave a previous successful route visible.
        if (pick === "start") setStart(null); else setEnd(null);
        return;
      }
      setPickError("");
      if (pick === "start") { setStart(point); setEnd(null); setPick("destination"); } else setEnd(point);
    } });
  }, [navigation, route, start, pick, onChange]);
  useEffect(() => () => onChange(null), [onChange]);
  const message = error || pickError || (route && !route.ok ? route.message : "");
  return <section aria-label="Automatic navigation" className="space-y-2">
    <p className="text-sm">Double-click or double-tap the floor to set {pick}. Drag to orbit.</p>
    <div className="flex flex-wrap gap-2">
      <button type="button" className="border rounded px-2 py-1" disabled={!navigation} aria-pressed={pick === "start"} onClick={() => setPick("start")}>Set start</button>
      <button type="button" className="border rounded px-2 py-1" disabled={!navigation || !start} aria-pressed={pick === "destination"} onClick={() => setPick("destination")}>Set destination</button>
      <button type="button" className="border rounded px-2 py-1" onClick={() => { setStart(null); setEnd(null); setPick("start"); setPickError(""); }}>Clear route</button>
    </div>
    {message ? <p role="alert">{message}</p> : <p role="status">{!navigation ? "Generating walkable floor…" : route?.ok ? `Route ready · ${approximate ? "≈ " : ""}${route.distance.toFixed(2)} m` : start ? "Start selected. Choose a destination." : "Walkable floor ready. Choose a start."}</p>}
    {route?.ok && <details className="text-sm">
      <summary className="cursor-pointer py-1 font-bold">Step-by-step directions</summary>
      <ol aria-label="Route directions" className="list-decimal pl-5">{routeDirections(route.points).map((step, i) => <li key={i}>{step}</li>)}</ol>
    </details>}
    {approximate && <p className="text-sm">Scale is unverified. This preview assumes the GLB uses metres and +Y up.</p>}
    <p className="text-xs">Preview from scan geometry · 0.30 m radius, 1.80 m height. Verify the route against the room.</p>
  </section>;
}
/** Metric agent settings cannot be applied to relative/unknown coordinates. */
export function automaticNavigationIssue(metadata: Record<string, unknown> | undefined): string | undefined {
  const frame = metadata?.coordinateSystem as { units?: unknown; upAxis?: unknown; calibrated?: unknown } | undefined;
  if (metadata?.alignmentVerified !== true || frame?.units !== "metres" || frame.upAxis !== "Y" || frame.calibrated !== true) {
    return "Automatic routing requires owner-verified alignment in calibrated metres with +Y up.";
  }
  return undefined;
}

/** A single GLB has its own frame: use glTF's metre/+Y convention for a preview.
 * Explicit relative or non-Y declarations still require owner calibration.
 * This never changes or asserts persisted calibration for a multi-scan space.
 */
export function singleScanNavigation(metadata: Record<string, unknown> | undefined) {
  const frame = metadata?.coordinateSystem as { units?: unknown; upAxis?: unknown } | undefined;
  const unavailable = (frame?.units !== undefined && frame.units !== "metres") ||
    (frame?.upAxis !== undefined && frame.upAxis !== "Y")
    ? "This model uses relative scale or a different up axis. Verify its scale and +Y floor orientation in Owner tools before routing."
    : undefined;
  return { unavailable, approximate: !!automaticNavigationIssue(metadata) };
}

